#!/usr/bin/env python3
import sys


def val_arg_tpls_sort(lis):
    val_arg_tpls = (
        (val, i) for i, val in enumerate(lis)
    )
    return list(sorted(val_arg_tpls))


def count_odd_in_even(val_arg_tpls):
    cnt = 0
    for _, arg in val_arg_tpls[::2]:
        cnt += arg % 2
    return cnt


def solve(N: int, A: "List[int]"):
    sorted_tpls = val_arg_tpls_sort(A)
    cnt = count_odd_in_even(sorted_tpls)
    print(cnt)
    return


# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    A = [int(next(tokens)) for _ in range(N)]  # type: "List[int]"
    solve(N, A)

if __name__ == '__main__':
    main()
